# Setup filtering constants
ALLOWED_EXTENSIONS = {
    '.py', '.js', '.ts', '.jsx', '.tsx', '.java', '.go', '.rb', '.php', 
    '.c', '.cpp', '.h', '.cs', '.md', '.json', '.yml', '.yaml', '.html', '.css'
}

CRITICAL_FILES = {
    'package.json', 'requirements.txt', '.env.example', 'pom.xml', 
    'go.mod', 'dockerfile', 'docker-compose.yml'
}

EXCLUDED_DIRS = {
