import React, { useState, useRef, useEffect } from 'react';
import { useUser } from '../context/UserContext';
import { useNavigate } from 'react-router-dom';
import './UserProfile.css';

export function UserProfile() {
    const { user, logout } = useUser();
    const [showDropdown, setShowDropdown] = useState(false);
    const dropdownRef = useRef(null);
    const navigate = useNavigate();

    useEffect(() => {
        function handleClickOutside(event) {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setShowDropdown(false);
            }
        }

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleLogout = async () => {
        await logout();
        navigate('/login');
    };

    if (!user) return null;

    return (
        <div className="user-profile" ref={dropdownRef}>
            <button
                className="profile-button"
                onClick={() => setShowDropdown(!showDropdown)}
                aria-label="User profile"
            >
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <circle cx="12" cy="8" r="4" fill="currentColor" />
                    <path d="M 4 20 C 4 15.58 7.58 12 12 12 C 16.42 12 20 15.58 20 20" fill="currentColor" />
                </svg>
            </button>

            {showDropdown && (
                <div className="profile-dropdown">
                    <div className="dropdown-header">
                        <p className="user-email">{user.email}</p>
                    </div>
                    <button className="logout-button" onClick={handleLogout}>
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M17 16L21 12M21 12L17 8M21 12H9M9 3H7C5.9 3 5 3.9 5 5V19C5 20.1 5.9 21 7 21H9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                        Logout
                    </button>
                </div>
            )}
        </div>
    );
}

import React, { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext();

export function ThemeProvider({ children }) {
    const [isDark, setIsDark] = useState(() => {
        // Check localStorage for saved theme preference
        const saved = localStorage.getItem('theme');
        if (saved) {
            return saved === 'dark';
        }
        // Default to dark mode
        return true;
    });

    useEffect(() => {
        // Update localStorage and DOM immediately
        localStorage.setItem('theme', isDark ? 'dark' : 'light');
        const root = document.documentElement;

        // Force immediate attribute update
        root.removeAttribute('data-theme');
        setTimeout(() => {
            root.setAttribute('data-theme', isDark ? 'dark' : 'light');
        }, 0);

        // Also add/remove class for extra specificity
        if (isDark) {
            root.classList.remove('light-mode');
            root.classList.add('dark-mode');
        } else {
            root.classList.remove('dark-mode');
            root.classList.add('light-mode');
        }
    }, [isDark]);

    const toggleTheme = () => {
        setIsDark(prev => !prev);
    };

    return (
        <ThemeContext.Provider value={{ isDark, toggleTheme }}>
            {children}
        </ThemeContext.Provider>
    );
}

export function useTheme() {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useTheme must be used within ThemeProvider');
    }
    return context;
}

import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth } from '../services/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const UserContext = createContext();

export function UserProvider({ children }) {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
            setUser(currentUser);
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const logout = async () => {
        try {
            await signOut(auth);
            setUser(null);
        } catch (err) {
            console.error('Logout error:', err);
        }
    };

    return (
        <UserContext.Provider value={{ user, loading, logout }}>
            {children}
        </UserContext.Provider>
    );
}

export function useUser() {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within UserProvider');
    }
    return context;
}

import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { HomePage } from "./pages/HomePage";
import { LoginPage } from "./pages/LoginPage";
import { SignUpPage } from "./pages/SignUpPage";
import { DashboardPage } from "./pages/DashboardPage";
import { AnalyseBranchesPage } from "./pages/AnalyseBranchesPage";
import { SecurityAuditPage } from "./pages/SecurityAuditPage";
import { DebtReportPage } from "./pages/DebtReportPage";
import { HealthScorePage } from "./pages/HealthScorePage";
import { AppLayout } from "./components/AppLayout";
import { ThemeProvider } from "./context/ThemeContext";
import { UserProvider, useUser } from "./context/UserContext";
import "./styles.css";

function ProtectedRoute({ children }) {
    const { user, loading } = useUser();

    if (loading) {
        return <div style={{ background: 'var(--bg)', height: '100vh' }} />;
    }

    if (!user) {
        return <Navigate to="/login" />;
    }

    return children;
}

function App() {
    return (
        <AppLayout>
            <Routes>
                <Route path="/" element={<HomePage />} />
                <Route path="/login" element={<LoginPage />} />
                <Route path="/signup" element={<SignUpPage />} />
                <Route
                    path="/dashboard"
                    element={
                        <ProtectedRoute>
                            <DashboardPage />
                        </ProtectedRoute>
                    }
                />
                <Route
                    path="/analyse-branches"
                    element={
                        <ProtectedRoute>
                            <AnalyseBranchesPage />
                        </ProtectedRoute>
                    }
                />
                <Route
                    path="/security-audit"
                    element={
                        <ProtectedRoute>
                            <SecurityAuditPage />
                        </ProtectedRoute>
                    }
                />
                <Route
                    path="/debt-report"
                    element={
                        <ProtectedRoute>
                            <DebtReportPage />
                        </ProtectedRoute>
                    }
                />
                <Route
                    path="/health-score"
                    element={
                        <ProtectedRoute>
                            <HealthScorePage />
                        </ProtectedRoute>
                    }
                />
            </Routes>
        </AppLayout>
    );
}

ReactDOM.createRoot(document.getElementById("root")).render(
    <React.StrictMode>
        <BrowserRouter>
            <ThemeProvider>
                <UserProvider>
                    <App />
                </UserProvider>
            </ThemeProvider>
        </BrowserRouter>
    </React.StrictMode>
);

